    mm::Image img_or  = mm::bor(img_gray, mask_circ);  // ilumina a região da máscara

    mm::show(
        std::vector&lt;mm::Image&gt;{img_gray, img_and, img_or, img_not},
        MM_OUT,
        std::vector&lt;std::string&gt;{"Original", "AND (ROI circular)", "OR (ilumina ROI)", "NOT (negativo)"},
        4
    );


