    img_gray.convertTo(img_float, CV_64F);

    std::vector&lt;std::string&gt; wavelets_comp = {"haar", "db4", "sym4", "bior2.2"};
    std::vector&lt;mm::Image&gt; imgs_comp;
    std::vector&lt;std::string&gt; titles_comp;

    for (const auto& wname : wavelets_comp) {
